import type { WidgetMessage } from "./types";
import { ACK_REQUIRED_TYPES, ACK_TIMEOUT_MS, ACK_MAX_RETRIES } from "./types";
import { log, warn } from "./debug";

type MessageHandler = (message: WidgetMessage) => void;

export class MessageBus {
  private iframe: HTMLIFrameElement | null = null;
  private allowedOrigins: string[] = [];
  private handlers: Map<string, MessageHandler[]> = new Map();
  private pendingAcks: Map<
    string,
    { resolve: (ack: WidgetMessage) => void; timer: ReturnType<typeof setTimeout>; retries: number; message: WidgetMessage }
  > = new Map();
  private messageQueue: WidgetMessage[] = [];
  private _isReady = false;
  private _unloadListener: ((e: MessageEvent) => void) | null = null;

  init(iframe: HTMLIFrameElement, allowedOrigins: string[]): void {
    this.iframe = iframe;
    this.allowedOrigins = allowedOrigins;
    this._unloadListener = this._handleMessage.bind(this);
    window.addEventListener("message", this._unloadListener);
    log("message bus: initialized");
  }

  setReady(ready: boolean): void {
    this._isReady = ready;
    if (ready) {
      this._flushQueue();
    }
  }

  send<T>(message: WidgetMessage<T>, requireAck = false): Promise<WidgetMessage | null> {
    if (!this.iframe?.contentWindow) {
      warn("message bus: iframe not ready, queuing message", message.type);
      this.messageQueue.push(message as WidgetMessage);
      return Promise.resolve(null);
    }

    if (!this._isReady && message.type !== "HELLO" && message.type !== "INIT") {
      this.messageQueue.push(message as WidgetMessage);
      log("message bus: queuing message (not ready)", message.type);
      return Promise.resolve(null);
    }

    this.iframe.contentWindow.postMessage(message, this.iframe.src ? new URL(this.iframe.src).origin : "*");
    log("message bus: sent", message.type, message.requestId);

    if (requireAck || ACK_REQUIRED_TYPES.has(message.type as typeof ACK_REQUIRED_TYPES extends Set<infer T> ? T : never)) {
      return this._waitForAck(message as WidgetMessage);
    }

    return Promise.resolve(null);
  }

  on(type: string, handler: MessageHandler): () => void {
    const handlers = this.handlers.get(type) ?? [];
    handlers.push(handler);
    this.handlers.set(type, handlers);
    return () => {
      const current = this.handlers.get(type) ?? [];
      this.handlers.set(
        type,
        current.filter((h) => h !== handler)
      );
    };
  }

  destroy(): void {
    if (this._unloadListener) {
      window.removeEventListener("message", this._unloadListener);
      this._unloadListener = null;
    }
    this.handlers.clear();
    for (const [, pending] of this.pendingAcks) {
      clearTimeout(pending.timer);
    }
    this.pendingAcks.clear();
    this.messageQueue = [];
    this.iframe = null;
    this._isReady = false;
    log("message bus: destroyed");
  }

  private _handleMessage(event: MessageEvent): void {
    if (!this.allowedOrigins.some((o) => o === event.origin)) return;

    const message = event.data as WidgetMessage;
    if (!message?.version || message.target !== "smart-ai-sdk") return;

    log("message bus: received", message.type, message.requestId);

    // Handle ACK responses
    if (message.type === "ACK") {
      const payload = message.payload as { originalType: string; requestId: string };
      const pending = this.pendingAcks.get(payload.requestId);
      if (pending) {
        clearTimeout(pending.timer);
        this.pendingAcks.delete(payload.requestId);
        pending.resolve(message);
      }
      return;
    }

    // Dispatch to handlers
    const handlers = this.handlers.get(message.type) ?? [];
    for (const handler of handlers) {
      handler(message);
    }
  }

  private _waitForAck(message: WidgetMessage): Promise<WidgetMessage | null> {
    return new Promise((resolve) => {
      let retries = 0;

      const startTimer = () => {
        const timer = setTimeout(() => {
          retries++;
          if (retries >= ACK_MAX_RETRIES) {
            this.pendingAcks.delete(message.requestId);
            warn("message bus: ACK timeout for", message.type, message.requestId);
            resolve(null);
            return;
          }
          log("message bus: ACK retry", retries, message.type);
          this.iframe?.contentWindow?.postMessage(message, this.iframe.src ? new URL(this.iframe.src).origin : "*");
          startTimer();
        }, ACK_TIMEOUT_MS);

        this.pendingAcks.set(message.requestId, { resolve, timer, retries, message });
      };

      startTimer();
    });
  }

  private _flushQueue(): void {
    const queue = [...this.messageQueue];
    this.messageQueue = [];
    for (const msg of queue) {
      this.send(msg);
    }
    log("message bus: flushed queue", queue.length, "messages");
  }
}
