import type { WidgetMessage, SmartAIConfig, InitPayload, ReadyPayload } from "./types";
import { MessageBus } from "./message-bus";
import { log, warn } from "./debug";

const HANDSHAKE_TIMEOUT_MS = 10000;

type HandshakeState = "idle" | "waiting_ack" | "waiting_ready" | "complete" | "failed";

export class Handshake {
  private _state: HandshakeState = "idle";
  private _resolveReady: ((payload: ReadyPayload) => void) | null = null;
  private _rejectReady: ((error: Error) => void) | null = null;
  private _timer: ReturnType<typeof setTimeout> | null = null;
  private _version: string = "1.0.0";

  get isComplete(): boolean {
    return this._state === "complete";
  }

  async execute(
    messageBus: MessageBus,
    config: SmartAIConfig
  ): Promise<ReadyPayload> {
    return new Promise<ReadyPayload>((resolve, reject) => {
      this._resolveReady = resolve;
      this._rejectReady = reject;

      // Listen for HELLO_ACK and READY
      messageBus.on("HELLO_ACK", (msg) => this._onHelloAck(msg, messageBus, config));
      messageBus.on("READY", (msg) => this._onReady(msg));

      // Set timeout
      this._timer = setTimeout(() => {
        if (this._state !== "complete") {
          this._state = "failed";
          reject(new Error("Handshake timeout"));
        }
      }, HANDSHAKE_TIMEOUT_MS);

      // Send HELLO to iframe
      this._state = "waiting_ack";
      const helloMsg: WidgetMessage = {
        version: "1.0",
        source: "smart-ai-sdk",
        target: "smart-ai-widget",
        type: "HELLO",
        requestId: crypto.randomUUID(),
        timestamp: Date.now(),
        payload: { sdkVersion: this._version },
      };
      messageBus.send(helloMsg);
      log("handshake: HELLO sent");
    });
  }

  private _onHelloAck(
    msg: WidgetMessage,
    messageBus: MessageBus,
    config: SmartAIConfig
  ): void {
    if (this._state !== "waiting_ack") return;

    log("handshake: HELLO_ACK received", msg.payload);
    this._state = "waiting_ready";

    // Send INIT with token and user info
    const initPayload: InitPayload = {
      appId: config.appId,
      token: config.token,
      user: config.user,
      theme: config.theme,
      context: config.context,
      debug: config.debug,
    };

    const initMsg: WidgetMessage<InitPayload> = {
      version: "1.0",
      source: "smart-ai-sdk",
      target: "smart-ai-widget",
      type: "INIT",
      requestId: crypto.randomUUID(),
      timestamp: Date.now(),
      payload: initPayload,
    };
    messageBus.send(initMsg);
    log("handshake: INIT sent");
  }

  private _onReady(msg: WidgetMessage): void {
    if (this._state !== "waiting_ready") return;

    const payload = msg.payload as ReadyPayload;
    log("handshake: READY received", payload);
    this._state = "complete";

    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }

    this._resolveReady?.(payload);
  }

  destroy(): void {
    if (this._timer) {
      clearTimeout(this._timer);
      this._timer = null;
    }
    this._state = "idle";
    this._resolveReady = null;
    this._rejectReady = null;
  }
}
