import { SmartAI } from "./sdk";

declare global {
  interface Window {
    SmartAI: SmartAI;
    smartAIConfig?: Partial<import("./types").SmartAIConfig>;
  }
}

// Prevent duplicate initialization
if (typeof window !== "undefined" && window.SmartAI) {
  console.warn("[SmartAI] SDK already loaded. Skipping duplicate initialization.");
} else {
  const instance = new SmartAI();
  window.SmartAI = instance;

  // Auto-init if global config is present and has required fields
  const config = window.smartAIConfig;
  if (config?.appId && config?.apiBase && config?.token && config?.user) {
    // Defer init to next tick so user can set up event listeners first
    setTimeout(() => {
      if (window.SmartAI.getState() === "IDLE") {
        window.SmartAI.init();
      }
    }, 0);
  }
}

export { SmartAI } from "./sdk";
export type { SmartAIConfig, SDKState, ThemeConfig, PageContext } from "./types";
