// SDK internal types — zero-dependency, no imports from host project.

export type Position = "right-bottom" | "left-bottom" | "right-top" | "left-top";

export interface ThemeConfig {
  primaryColor?: string;
  mode?: "light" | "dark";
  position?: Position;
  iconUrl?: string;
  buttonStyle?: {
    backgroundColor?: string;
    borderColor?: string;
    size?: number;
  };
}

export interface PageContext {
  currentPage?: string;
  activeModule?: string;
  selectedItems?: string[];
  metadata?: Record<string, unknown>;
}

export interface SmartAIConfig {
  // Required
  appId: string;
  apiBase: string;
  token: string;
  // User info
  user: {
    id: string;
    name: string;
    [key: string]: unknown;
  };
  // Optional
  theme?: ThemeConfig;
  context?: PageContext;
  position?: Position;
  debug?: boolean;
  preload?: boolean;
  locale?: string;
}

export type SDKState =
  | "IDLE"
  | "LOADING"
  | "HANDSHAKE"
  | "AUTHENTICATING"
  | "READY"
  | "OPEN"
  | "CLOSED"
  | "ERROR"
  | "DESTROYED";

export type MessageSource = "smart-ai-sdk" | "smart-ai-widget";
export type MessageTarget = "smart-ai-sdk" | "smart-ai-widget";

export interface WidgetMessage<T = unknown> {
  version: "1.0";
  source: MessageSource;
  target: MessageTarget;
  type: string;
  requestId: string;
  timestamp: number;
  payload: T;
}

export type StateChangeCallback = (from: SDKState, to: SDKState) => void;
export type EventCallback = (payload: unknown) => void;

// Critical messages that require ACK
export const ACK_REQUIRED_TYPES = new Set([
  "HELLO",
  "INIT",
  "AUTH_EXPIRED",
]);

export const ACK_TIMEOUT_MS = 5000;
export const ACK_MAX_RETRIES = 3;
