import type { SmartAIConfig } from "./types";
import { log, warn } from "./debug";

const IFRAME_ID = "smart-ai-widget-iframe";
const TRANSITION_DURATION = "0.35s";
const TRANSITION_EASING = "cubic-bezier(0.4, 0, 0.2, 1)";
const DEFAULT_TRANSITION = `opacity ${TRANSITION_DURATION} ${TRANSITION_EASING}, transform ${TRANSITION_DURATION} ${TRANSITION_EASING}, visibility ${TRANSITION_DURATION}`;
const FULLSCREEN_TRANSITION = `width ${TRANSITION_DURATION} ${TRANSITION_EASING}, height ${TRANSITION_DURATION} ${TRANSITION_EASING}, top ${TRANSITION_DURATION} ${TRANSITION_EASING}, right ${TRANSITION_DURATION} ${TRANSITION_EASING}, bottom ${TRANSITION_DURATION} ${TRANSITION_EASING}, left ${TRANSITION_DURATION} ${TRANSITION_EASING}, border-radius ${TRANSITION_DURATION} ${TRANSITION_EASING}, box-shadow ${TRANSITION_DURATION} ${TRANSITION_EASING}`;

export class IframeManager {
  private iframe: HTMLIFrameElement | null = null;
  private _isVisible = false;
  private _isFullscreen = false;
  private _position: string = "right-bottom";

  get isCreated(): boolean {
    return this.iframe !== null;
  }

  get isFullscreen(): boolean {
    return this._isFullscreen;
  }

  get isVisible(): boolean {
    return this._isVisible;
  }

  create(config: SmartAIConfig): HTMLIFrameElement {
    if (this.iframe) {
      warn("iframe manager: iframe already exists");
      return this.iframe;
    }

    this._position = config.position ?? config.theme?.position ?? "right-bottom";

    const iframe = document.createElement("iframe");
    iframe.id = IFRAME_ID;

    const srcUrl = this._buildSrcUrl(config);
    iframe.src = srcUrl;

    Object.assign(iframe.style, {
      position: "fixed",
      zIndex: "2147483646",
      border: "none",
      width: "400px",
      height: "600px",
      maxWidth: "100vw",
      maxHeight: "100vh",
      borderRadius: "12px",
      boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
      overflow: "hidden",
      background: "transparent",
      // Hidden state — preloaded but invisible
      opacity: "0",
      visibility: "hidden",
      transform: "scale(0.4)",
      pointerEvents: "none",
      transition: DEFAULT_TRANSITION,
      ...this._getPositionStyles(this._position),
      ...this._getTransformOrigin(this._position),
    });

    // Accessibility
    iframe.setAttribute("title", "AI Chat Assistant");
    iframe.setAttribute("allow", "clipboard-write; fullscreen; microphone");

    document.body.appendChild(iframe);
    this.iframe = iframe;
    this._isVisible = false;

    log("iframe manager: created with src", srcUrl);
    return iframe;
  }

  show(): void {
    if (!this.iframe) return;
    // Animate in: scale up from small + fade in
    Object.assign(this.iframe.style, {
      visibility: "visible",
      opacity: "1",
      transform: "scale(1)",
      pointerEvents: "auto",
    });
    this._isVisible = true;
    log("iframe manager: shown");
  }

  hide(): void {
    if (!this.iframe) return;
    // Animate out: scale down + fade out
    Object.assign(this.iframe.style, {
      opacity: "0",
      transform: "scale(0.4)",
      pointerEvents: "none",
    });
    // Use visibility:hidden after transition completes to allow re-interaction
    setTimeout(() => {
      if (this.iframe && !this._isVisible) {
        this.iframe.style.visibility = "hidden";
      }
    }, 350);
    this._isVisible = false;
    log("iframe manager: hidden");
  }

  toggle(): boolean {
    if (this._isVisible) {
      this.hide();
    } else {
      this.show();
    }
    return this._isVisible;
  }

  setFullscreen(fullscreen: boolean): void {
    if (!this.iframe) return;
    if (this._isFullscreen === fullscreen) return;
    this._isFullscreen = fullscreen;

    if (fullscreen) {
      this._expandToFullscreen();
    } else {
      this._shrinkFromFullscreen();
    }
  }

  private _expandToFullscreen(): void {
    const iframe = this.iframe!;

    iframe.style.transition = FULLSCREEN_TRANSITION;
    Object.assign(iframe.style, {
      width: "100vw",
      height: "100vh",
      top: "0",
      right: "0",
      bottom: "0",
      left: "0",
      maxWidth: "100vw",
      maxHeight: "100vh",
      borderRadius: "0",
      boxShadow: "none",
    });

    log("iframe manager: expanding to fullscreen");
  }

  private _shrinkFromFullscreen(): void {
    const iframe = this.iframe!;

    iframe.style.transition = FULLSCREEN_TRANSITION;
    Object.assign(iframe.style, {
      width: "400px",
      height: "600px",
      maxWidth: "100vw",
      maxHeight: "100vh",
      top: "",
      left: "",
      bottom: "",
      right: "",
      borderRadius: "12px",
      boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
      ...this._getPositionStyles(this._position),
    });

    setTimeout(() => {
      if (this.iframe && !this._isFullscreen) {
        this.iframe.style.transition = DEFAULT_TRANSITION;
      }
    }, 350);

    log("iframe manager: shrinking from fullscreen");
  }

  getIframe(): HTMLIFrameElement | null {
    return this.iframe;
  }

  destroy(): void {
    if (this.iframe) {
      this.iframe.remove();
      this.iframe = null;
      this._isVisible = false;
      this._isFullscreen = false;
    }
    log("iframe manager: destroyed");
  }

  private _buildSrcUrl(config: SmartAIConfig): string {
    const url = new URL("/embed/chat", config.apiBase);
    url.searchParams.set("appId", config.appId);
    if (config.theme) {
      url.searchParams.set("theme", JSON.stringify(config.theme));
    }
    if (config.locale) {
      url.searchParams.set("locale", config.locale);
    }
    url.searchParams.set("v", "1.0.0");
    return url.toString();
  }

  private _getPositionStyles(
    position: string = "right-bottom"
  ): Partial<CSSStyleDeclaration> {
    switch (position) {
      case "left-bottom":
        return { bottom: "90px", left: "20px" };
      case "right-top":
        return { top: "20px", right: "20px" };
      case "left-top":
        return { top: "20px", left: "20px" };
      case "right-bottom":
      default:
        return { bottom: "90px", right: "20px" };
    }
  }

  private _getTransformOrigin(
    position: string = "right-bottom"
  ): Partial<CSSStyleDeclaration> {
    switch (position) {
      case "left-bottom":
        return { transformOrigin: "bottom left" };
      case "right-top":
        return { transformOrigin: "top right" };
      case "left-top":
        return { transformOrigin: "top left" };
      case "right-bottom":
      default:
        return { transformOrigin: "bottom right" };
    }
  }
}
