import type { SDKState, StateChangeCallback } from "./types";

type TransitionMap = Record<SDKState, SDKState[]>;

const VALID_TRANSITIONS: TransitionMap = {
  IDLE: ["LOADING", "ERROR", "DESTROYED"],
  LOADING: ["HANDSHAKE", "ERROR", "DESTROYED"],
  HANDSHAKE: ["AUTHENTICATING", "ERROR", "DESTROYED"],
  AUTHENTICATING: ["READY", "ERROR", "DESTROYED"],
  READY: ["OPEN", "CLOSED", "ERROR", "DESTROYED"],
  OPEN: ["CLOSED", "ERROR", "DESTROYED"],
  CLOSED: ["OPEN", "ERROR", "DESTROYED"],
  ERROR: ["LOADING", "DESTROYED"],
  DESTROYED: [],
};

export class StateMachine {
  private _state: SDKState = "IDLE";
  private _listeners: StateChangeCallback[] = [];

  get state(): SDKState {
    return this._state;
  }

  onStateChange(cb: StateChangeCallback): () => void {
    this._listeners.push(cb);
    return () => {
      this._listeners = this._listeners.filter((l) => l !== cb);
    };
  }

  transition(to: SDKState): boolean {
    const from = this._state;
    if (from === to) return true;
    if (!VALID_TRANSITIONS[from].includes(to)) {
      console.warn(
        `[SmartAI] Invalid state transition: ${from} → ${to}`
      );
      return false;
    }
    this._state = to;
    for (const cb of this._listeners) {
      cb(from, to);
    }
    return true;
  }

  is(state: SDKState): boolean {
    return this._state === state;
  }

  isReady(): boolean {
    return (
      this._state === "READY" ||
      this._state === "OPEN" ||
      this._state === "CLOSED"
    );
  }

  isDestroyed(): boolean {
    return this._state === "DESTROYED";
  }
}
