import type { ThemeConfig, Position } from "./types";
import { log } from "./debug";

const Z_INDEX = 2147483647; // max 32-bit int
const DEFAULT_SIZE = 56;
const DEFAULT_COLOR = "#1677ff";

interface FloatingButtonOptions {
  position?: Position;
  theme?: ThemeConfig;
  onClick: () => void;
}

export class FloatingButton {
  private el: HTMLButtonElement | null = null;
  private _onClick: () => void;

  constructor(private options: FloatingButtonOptions) {
    this._onClick = options.onClick;
  }

  render(): HTMLButtonElement {
    if (this.el) return this.el;

    const btn = document.createElement("button");
    btn.setAttribute("aria-label", "Open AI Assistant");
    btn.setAttribute("role", "button");

    const pos = this.options.position ?? this.options.theme?.position ?? "right-bottom";
    const size = this.options.theme?.buttonStyle?.size ?? DEFAULT_SIZE;
    const bg = this.options.theme?.buttonStyle?.backgroundColor
      ?? this.options.theme?.primaryColor
      ?? DEFAULT_COLOR;

    Object.assign(btn.style, {
      position: "fixed",
      zIndex: String(Z_INDEX),
      width: `${size}px`,
      height: `${size}px`,
      borderRadius: "50%",
      border: "none",
      backgroundColor: bg,
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
      transition: "transform 0.2s, box-shadow 0.2s",
      ...this._getPositionStyles(pos, size),
    });

    btn.innerHTML = this._getIcon();
    btn.addEventListener("click", () => this._onClick());

    btn.addEventListener("mouseenter", () => {
      btn.style.transform = "scale(1.1)";
      btn.style.boxShadow = "0 6px 16px rgba(0,0,0,0.4)";
    });
    btn.addEventListener("mouseleave", () => {
      btn.style.transform = "scale(1)";
      btn.style.boxShadow = "0 4px 12px rgba(0,0,0,0.3)";
    });

    document.body.appendChild(btn);
    this.el = btn;
    log("floating button: rendered at", pos);
    return btn;
  }

  updateTheme(theme: ThemeConfig): void {
    if (!this.el) return;
    const bg = theme.buttonStyle?.backgroundColor ?? theme.primaryColor ?? DEFAULT_COLOR;
    this.el.style.backgroundColor = bg;
  }

  show(): void {
    if (this.el) this.el.style.display = "flex";
  }

  hide(): void {
    if (this.el) this.el.style.display = "none";
  }

  setErrorState(): void {
    if (!this.el) return;
    this.el.style.backgroundColor = "#f44336";
  }

  destroy(): void {
    if (this.el) {
      this.el.remove();
      this.el = null;
    }
    log("floating button: destroyed");
  }

  private _getPositionStyles(pos: Position, size: number): Partial<CSSStyleDeclaration> {
    const gap = "20px";
    switch (pos) {
      case "left-bottom":
        return { bottom: gap, left: gap };
      case "right-top":
        return { top: gap, right: gap };
      case "left-top":
        return { top: gap, left: gap };
      case "right-bottom":
      default:
        return { bottom: gap, right: gap };
    }
  }

  private _getIcon(): string {
    if (this.options.theme?.iconUrl) {
      return `<img src="${this.options.theme.iconUrl}" alt="AI" style="width:100%;height:100%;border-radius:50%;pointer-events:none" />`;
    }
    return `<img src="data:image/png;base64," alt="AI" style="width:100%;height:100%;border-radius:50%;pointer-events:none" />`;
  }
}
