import type { SmartAIConfig, SDKState, ThemeConfig, PageContext, EventCallback, WidgetMessage } from "./types";
import { StateMachine } from "./state-machine";
import { MessageBus } from "./message-bus";
import { IframeManager } from "./iframe-manager";
import { Handshake } from "./handshake";
import { FloatingButton } from "./floating-button";
import { initDebug, log, error } from "./debug";

type QueuedAction = () => void;

export class SmartAI {
  private config!: SmartAIConfig;
  private stateMachine = new StateMachine();
  private messageBus = new MessageBus();
  private iframeManager = new IframeManager();
  private handshake: Handshake | null = null;
  private floatingButton: FloatingButton | null = null;
  private eventListeners: Map<string, Set<EventCallback>> = new Map();
  private actionQueue: QueuedAction[] = [];

  init(config?: Partial<SmartAIConfig>): void {
    if (this.stateMachine.isDestroyed()) {
      console.warn("[SmartAI] Cannot init — already destroyed");
      return;
    }
    if (!this.stateMachine.is("IDLE")) {
      console.warn("[SmartAI] Already initialized, state:", this.stateMachine.state);
      return;
    }

    // Merge config: window.smartAIConfig as base, override with passed config
    const globalConfig = (window as unknown as { smartAIConfig?: Partial<SmartAIConfig> }).smartAIConfig;
    this.config = { ...globalConfig, ...config } as SmartAIConfig;

    if (!this.config.appId || !this.config.apiBase || !this.config.token || !this.config.user) {
      console.error("[SmartAI] Missing required config: appId, apiBase, token, user");
      this.stateMachine.transition("ERROR");
      return;
    }

    initDebug(this.config.debug ?? false);
    log("init: starting with appId", this.config.appId);

    // State transitions
    this.stateMachine.onStateChange((from, to) => {
      log(`state: ${from} → ${to}`);
    });

    // Create iframe (preload)
    this.stateMachine.transition("LOADING");
    const iframe = this.iframeManager.create(this.config);

    const widgetOrigin = new URL(this.config.apiBase).origin;
    this.messageBus.init(iframe, [widgetOrigin]);

    // Listen for iframe → SDK notifications
    this._setupNotificationListeners();

    // Start handshake once iframe loads
    iframe.addEventListener("load", () => {
      log("init: iframe loaded");
      this.stateMachine.transition("HANDSHAKE");

      this.handshake = new Handshake();
      this.handshake
        .execute(this.messageBus, this.config)
        .then((readyPayload) => {
          this.stateMachine.transition("READY");
          this.messageBus.setReady(true);

          // Send OPEN if user already clicked
          this._flushActionQueue();

          log("init: ready, hasHistory =", readyPayload.hasHistory);
        })
        .catch((err) => {
          error("init: handshake failed", err);
          this.stateMachine.transition("ERROR");
          this.floatingButton?.setErrorState();
        });
    });

    // Create floating button
    this.floatingButton = new FloatingButton({
      position: this.config.position,
      theme: this.config.theme,
      onClick: () => this.toggle(),
    });
    this.floatingButton.render();
  }

  open(): void {
    // Show iframe immediately for instant visual feedback, even if still loading
    if (this.stateMachine.is("LOADING") || this.stateMachine.is("HANDSHAKE")) {
      this.iframeManager.show();
    }

    this._enqueueOrExecute(() => {
      if (this.stateMachine.is("READY") || this.stateMachine.is("CLOSED")) {
        this.stateMachine.transition("OPEN");
        this.iframeManager.show();
        this.messageBus.send(this._createMessage("OPEN", {}));
      }
    });
  }

  close(): void {
    console.log('log=close=1>>>', "close")
    this._enqueueOrExecute(() => {
      if (this.stateMachine.is("OPEN")) {
        this.stateMachine.transition("CLOSED");
        this.iframeManager.hide();
        this.messageBus.send(this._createMessage("CLOSE", {}));
      }
    });
  }

  toggle(): void {
    if (this.iframeManager.isVisible) {
      const wasFullscreen = this.iframeManager.isFullscreen;

      // Reset fullscreen to normal state first
      if (wasFullscreen) {
        this.iframeManager.setFullscreen(false);
      }

      // Notify widget to reset fullscreen state
      this.messageBus.send(this._createMessage("FULLSCREEN", { isFullscreen: false }));

      const hideDelay = wasFullscreen ? 350 : 0;
      setTimeout(() => {
        this.iframeManager.hide();
        if (this.stateMachine.is("OPEN")) {
          this.stateMachine.transition("CLOSED");
        }
        this.messageBus.send(this._createMessage("CLOSE", {}));
      }, hideDelay);
    } else {
      this.open();
    }
  }

  updateContext(context: PageContext): void {
    this._enqueueOrExecute(() => {
      this.messageBus.send(this._createMessage("CONTEXT_UPDATE", context));
      log("updateContext:", context);
    });
  }

  setTheme(theme: ThemeConfig): void {
    this._enqueueOrExecute(() => {
      this.config.theme = { ...this.config.theme, ...theme };
      this.floatingButton?.updateTheme(this.config.theme);
      this.messageBus.send(this._createMessage("THEME_CHANGE", this.config.theme));
      log("setTheme:", theme);
    });
  }

  setToken(token: string): void {
    this.config.token = token;
    this._enqueueOrExecute(() => {
      this.messageBus.send(this._createMessage("INIT", {
        appId: this.config.appId,
        token,
        user: this.config.user,
      }));
      log("setToken: updated");
    });
  }

  on(event: string, callback: EventCallback): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(callback);
  }

  off(event: string, callback: EventCallback): void {
    this.eventListeners.get(event)?.delete(callback);
  }

  getState(): SDKState {
    return this.stateMachine.state;
  }

  destroy(): void {
    this.stateMachine.transition("DESTROYED");
    this.handshake?.destroy();
    this.messageBus.destroy();
    this.iframeManager.destroy();
    this.floatingButton?.destroy();
    this.eventListeners.clear();
    this.actionQueue = [];
    log("destroy: complete");
  }

  // --- Private ---

  private _setupNotificationListeners(): void {
    const emit = (event: string, payload: unknown) => {
      this.eventListeners.get(event)?.forEach((cb) => cb(payload));
    };

    this.messageBus.on("RESIZE", (msg) => emit("RESIZE", msg.payload));
    this.messageBus.on("FULLSCREEN", (msg) => {
      const payload = msg.payload as { isFullscreen: boolean };
      this.iframeManager.setFullscreen(payload.isFullscreen);
      emit("FULLSCREEN", payload);
    });
    this.messageBus.on("CLOSE", () => {
      if (this.iframeManager.isFullscreen) {
        this.iframeManager.setFullscreen(false);
      }
      this.iframeManager.hide();
      if (this.stateMachine.is("OPEN")) {
        this.stateMachine.transition("CLOSED");
      }
    });
    this.messageBus.on("AUTH_EXPIRED", (msg) => emit("AUTH_EXPIRED", msg.payload));
    this.messageBus.on("NEW_MESSAGE", (msg) => emit("NEW_MESSAGE", msg.payload));
    this.messageBus.on("TASK_COMPLETE", (msg) => emit("TASK_COMPLETE", msg.payload));
    this.messageBus.on("NAVIGATE", (msg) => emit("NAVIGATE", msg.payload));
    this.messageBus.on("ERROR", (msg) => {
      error("notification:", msg.payload);
      emit("ERROR", msg.payload);
    });
  }

  private _enqueueOrExecute(action: QueuedAction): void {
    if (this.stateMachine.isReady()) {
      action();
    } else {
      this.actionQueue.push(action);
      log("action queued (state:", this.stateMachine.state, ")");
    }
  }

  private _flushActionQueue(): void {
    const queue = [...this.actionQueue];
    this.actionQueue = [];
    for (const action of queue) {
      action();
    }
  }

  private _createMessage<T>(type: string, payload: T): WidgetMessage<T> {
    return {
      version: "1.0",
      source: "smart-ai-sdk",
      target: "smart-ai-widget",
      type,
      requestId: crypto.randomUUID(),
      timestamp: Date.now(),
      payload,
    };
  }
}
